using Arena.Editor.Art;
using Arena.Gameplay.View;
using Arena.UI.Style;
using NUnit.Framework;
using UnityEditor;
using UnityEngine;

namespace Arena.Tests.EditMode.Setup
{
    /// <summary>Assets generated by ViewAssetBuilder (D-014): catalog complete, prefabs without colliders, URP materials.</summary>
    public sealed class ViewAssetsTests
    {
        [Test]
        public void ViewCatalog_IsComplete_AndUsesUrpMaterials()
        {
            var catalog = AssetDatabase.LoadAssetAtPath<ViewCatalog>(ViewAssetBuilder.ViewCatalogPath);
            Assert.IsNotNull(catalog, ViewAssetBuilder.ViewCatalogPath);
            Assert.IsNotNull(catalog.FighterViewPrefab);
            Assert.IsNotNull(catalog.AimIndicatorPrefab);
            Assert.IsNotNull(catalog.FloorPrefab);
            Assert.IsNotNull(catalog.ProjectilePrefab);
            Assert.IsNotNull(catalog.HealthBarPrefab);
            Assert.Greater(catalog.ProjectilePoolPrewarm, 0);
            Material[] materials =
            {
                catalog.TeamAlly, catalog.TeamEnemy, catalog.FighterBody, catalog.Floor, catalog.AimLine, catalog.Projectile,
                catalog.BarAlly, catalog.BarEnemy, catalog.BarBackground, catalog.BarCharge
            };
            foreach (Material m in materials)
            {
                Assert.IsNotNull(m);
                StringAssert.StartsWith("Universal Render Pipeline/", m.shader.name, m.name);
            }
            Assert.AreNotEqual(catalog.TeamAlly.GetColor("_BaseColor"), catalog.TeamEnemy.GetColor("_BaseColor"));
        }

        [Test]
        public void Prefabs_HaveViewReferences_AndNoColliders()
        {
            var catalog = AssetDatabase.LoadAssetAtPath<ViewCatalog>(ViewAssetBuilder.ViewCatalogPath);
            Assert.IsNotNull(catalog.FighterViewPrefab.Body);
            Assert.IsNotNull(catalog.FighterViewPrefab.Ring);
            Assert.IsNotNull(catalog.AimIndicatorPrefab.Line);
            Assert.IsNotNull(catalog.HealthBarPrefab.FillPivot);
            Assert.IsNotNull(catalog.HealthBarPrefab.Fill);
            Assert.AreEqual(3, catalog.HealthBarPrefab.SegmentCount, "one segment per attack charge (GDD §5.2)");
            GameObject[] prefabs =
            {
                catalog.FighterViewPrefab.gameObject, catalog.AimIndicatorPrefab.gameObject, catalog.FloorPrefab,
                catalog.ProjectilePrefab, catalog.HealthBarPrefab.gameObject
            };
            foreach (GameObject p in prefabs)
                Assert.AreEqual(0, p.GetComponentsInChildren<Collider>(true).Length, p.name + " has colliders");
        }

        [Test]
        public void UiStyle_HasSpriteAndSaneGestureThresholds()
        {
            var style = AssetDatabase.LoadAssetAtPath<UiStyle>(ViewAssetBuilder.UiStylePath);
            Assert.IsNotNull(style, ViewAssetBuilder.UiStylePath);
            Assert.IsNotNull(style.CircleSprite);
            Assert.Greater(style.ReferenceResolution.x, 0f);
            Assert.Greater(style.Gesture.DeadZone, 0f);
            Assert.Less(style.Gesture.DeadZone, 1f);
            Assert.Less(style.Gesture.CancelRadius, 1f);
            Assert.Greater(style.Gesture.TapMaxSeconds, 0f);
            Assert.Greater(style.MoveStick.Radius, 0f);
            Assert.Greater(style.AttackStick.Radius, 0f);
            Assert.Greater(style.UltStick.Radius, 0f);
        }
    }
}
